param([Parameter(Mandatory)][string]$ServiceId,[Parameter(Mandatory)][string]$ParametersFile,[Parameter(Mandatory)][string]$SigningPrivateKeyFile,[Parameter(Mandatory)][string]$SigningKeyId,[Parameter(Mandatory)][string]$OutputDirectory)
$ErrorActionPreference='Stop';. "$PSScriptRoot/BackupRestore.Common.ps1";$required=@('DeploymentRoot','ConfirmDeploymentRoot','DeploymentId','SecretRoot','StatePrivateKeyFile','StatePublicKeyFile','StateSignerKeyId','CurrentSlotDirectory','CurrentTrustedPublicKeyFile','CurrentExpectedSigningKeyId','CandidateSlotDirectory','CandidateTrustedPublicKeyFile','CandidateExpectedSigningKeyId','ExpectedPackageSupplier','ExpectedSbomNamespaceBase','PlanFile','RequesterPublicKeyFile','ExpectedRequesterKeyId','ApproverPublicKeyFile','ExpectedApproverKeyId','MonitoringPublicKeyFile','ExpectedMonitoringKeyId','ObservationFile','ObservationSignatureFile','ExpectedWavePercent','ServerArguments');$forbidden=@('ExitAfterSuccessfulSwitch','TestOnlySuppressCurrentShutdown','AllowTestPlan','AllowDirtyTestArtifact')
if($ServiceId-notmatch'^[A-Za-z][A-Za-z0-9._-]{2,63}$'){throw 'ServiceId is invalid'};$parameters=Get-Content ([IO.Path]::GetFullPath($ParametersFile)) -Raw|ConvertFrom-Json -Depth 20 -DateKind String;$names=@($parameters.PSObject.Properties.Name);foreach($name in $required){if($name -notin $names-or[string]::IsNullOrWhiteSpace([string]$parameters.$name)){throw "Supervisor parameter is missing: $name"}};foreach($name in $forbidden){if($name -in $names){throw "Test-only supervisor parameter is forbidden: $name"}}
$fingerprint=Get-BackupKeyFingerprint $SigningPrivateKeyFile 'Supervisor configuration' $true;$config=[ordered]@{SchemaVersion=1;Product='ET.Server';ArtifactType='ServerSupervisorConfiguration';ServiceId=$ServiceId;SignerKeyId=$SigningKeyId;SignerPublicKeySha256=$fingerprint;CreatedAtUtc=[DateTimeOffset]::UtcNow.ToString('O');SupervisorParameters=$parameters};$output=Assert-BackupPathOutsideRepository $OutputDirectory 'OutputDirectory';New-Item -ItemType Directory $output -Force|Out-Null;$file=Join-Path $output "$ServiceId.supervisor.json";if((Test-Path $file)-or(Test-Path "$file.sig")){throw 'Supervisor configuration already exists'};$bytes=[Text.UTF8Encoding]::new($false).GetBytes(($config|ConvertTo-Json -Depth 20));try{[IO.File]::WriteAllBytes($file,$bytes);[IO.File]::WriteAllBytes("$file.sig",(New-BackupSignature $bytes $SigningPrivateKeyFile 'Supervisor configuration'));[ordered]@{Passed=$true;ConfigurationFile=$file;SignatureFile="$file.sig";ServiceId=$ServiceId;ConfigurationSha256=(Get-FileHash $file -Algorithm SHA256).Hash.ToLowerInvariant()}|ConvertTo-Json}catch{foreach($path in @($file,"$file.sig")){if(Test-Path $path){Remove-Item $path -Force}};throw}
